svg.script:
const NS = "http://www.w3.org/2000/svg", W = 680, H = 400;
const svg = document.documentElement, ink = document.getElementById("ink");
const strokes = [];
let call = null, response = null, hum = null;
let lastInput = performance.now() - 4000;

function el(cls) {
  const e = document.createElementNS(NS, "path");
  e.setAttribute("class", cls);
  ink.appendChild(e);
  return e;
}

function smoothD(pts) {
  if (pts.length < 2) return "";
  let d = `M${pts[0].x.toFixed(1)} ${pts[0].y.toFixed(1)}`;
  for (let i = 1; i < pts.length - 1; i++) {
    const mx = (pts[i].x + pts[i + 1].x) / 2, my = (pts[i].y + pts[i + 1].y) / 2;
    d += ` Q${pts[i].x.toFixed(1)} ${pts[i].y.toFixed(1)} ${mx.toFixed(1)} ${my.toFixed(1)}`;
  }
  const l = pts[pts.length - 1];
  return d + ` L${l.x.toFixed(1)} ${l.y.toFixed(1)}`;
}

function fade(e, now, life) { strokes.push({ el: e, born: now, life }); }

// The answer: mirrored across the center line, smoothed, with a flourish of its own
function answer(src, now) {
  const n = src.length, sm = [];
  for (let i = 0; i < n; i++) {
    let x = 0, y = 0, c = 0;
    for (let j = Math.max(0, i - 3); j <= Math.min(n - 1, i + 3); j++) { x += src[j].x; y += src[j].y; c++; }
    sm.push({ x: W - x / c, y: y / c, t: src[i].t });
  }
  const phase = Math.random() * 6.283, amp = 5 + Math.random() * 6;
  const pts = sm.map((p, i) => {
    const a = sm[Math.max(0, i - 1)], b = sm[Math.min(n - 1, i + 1)];
    const dx = b.x - a.x, dy = b.y - a.y, len = Math.hypot(dx, dy) || 1;
    const env = Math.sin(Math.PI * i / (n - 1));
    const off = amp * env * Math.sin(i * 0.32 + phase);
    return { x: p.x - dy / len * off, y: p.y + dx / len * off, t: p.t };
  });
  const t0 = pts[0].t;
  response = { el: el("resp"), pts, times: pts.map(p => (p.t - t0) * 1.25), start: now + 350 };
}

function startHum(now) {
  const ratios = [[1, 2], [2, 3], [3, 2], [1, 3], [3, 4]];
  const [a, b] = ratios[Math.floor(Math.random() * ratios.length)];
  const d = Math.random() * 3, pts = [];
  for (let i = 0; i <= 260; i++) {
    const t = i / 260 * 6.283;
    pts.push({ x: W / 2 + 150 * Math.sin(a * t + d), y: H / 2 - 10 + 120 * Math.sin(b * t) });
  }
  hum = { el: el("hum"), pts, start: now, dur: 7000 };
  hum.el.setAttribute("stroke-opacity", "0.45");
}

function toSvg(ev) {
  const pt = svg.createSVGPoint();
  pt.x = ev.clientX; pt.y = ev.clientY;
  return pt.matrixTransform(svg.getScreenCTM().inverse());
}

svg.addEventListener("pointermove", ev => {
  const now = performance.now(), p = toSvg(ev);
  if (p.y > H) return;
  lastInput = now;
  if (!call) call = { el: el("call"), pts: [] };
  const l = call.pts[call.pts.length - 1];
  if (!l || Math.hypot(p.x - l.x, p.y - l.y) > 4) {
    call.pts.push({ x: p.x, y: p.y, t: now });
    call.el.setAttribute("d", smoothD(call.pts));
  }
});

function frame(now) {
  // A pause ends the call and invites an answer
  if (call && now - lastInput > 600) {
    fade(call.el, now, 7000);
    if (call.pts.length >= 8 && !response) answer(call.pts, now);
    call = null;
  }

  if (response && now >= response.start) {
    const e = now - response.start, r = response;
    let k = 0;
    while (k < r.pts.length && r.times[k] <= e) k++;
    r.el.setAttribute("d", smoothD(r.pts.slice(0, Math.max(2, k))));
    if (k >= r.pts.length) { fade(r.el, now, 9000); response = null; }
  }

  if (!hum && !call && !response && now - lastInput > 6000) startHum(now);
  if (hum) {
    const u = Math.min(1, (now - hum.start) / hum.dur);
    hum.el.setAttribute("d", smoothD(hum.pts.slice(0, Math.max(2, Math.floor(u * hum.pts.length)))));
    if (u >= 1 || call) { fade(hum.el, now, 4000); hum = null; lastInput = Math.max(lastInput, now - 2000); }
  }

  for (let i = strokes.length - 1; i >= 0; i--) {
    const s = strokes[i], f = 1 - (now - s.born) / s.life;
    if (f <= 0) { s.el.remove(); strokes.splice(i, 1); }
    else s.el.setAttribute("opacity", f.toFixed(3));
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
